INSERT INTO skillup_dev.career_learning_resources
(id, programme_id, domain_id, subgroup_id, role_id, ownership_scope, review_status, resource_type, target_name, provider, region, access_type, delivery, url, source_url, description, source_confidence, data_state, source_provenance)
SELECT gen_random_uuid(), p.id, NULL, NULL, NULL, 'programme', 'approved_guidance_v1', r.resource_type, r.target_name, r.provider, r.region, r.access_type, r.delivery, r.url, r.source_url, r.description, 'high', 'source_backed', r.provenance
FROM resource_rows r
JOIN skillup_dev.programmes p ON lower(trim(p.discipline)) = lower(trim(r.discipline)) AND lower(trim(p.name)) = lower(trim(r.programme))
ON CONFLICT DO NOTHING;

WITH context_rows(discipline, programme, item_type, item_key, name, plain_meaning, contextual_use, expected_output, priority, priority_reason, prerequisites, related_items, source_ids, source_references, source_locators, geographic_scope, evidence_limitations) AS (
VALUES
('Administration and Management', 'Accounting', 'skill', 'understand-programme-foundation', 'Understand Accounting', 'Accounting brings together research and evidence, mathematics and quantitative reasoning, laboratory and scientific practice, people, society and institutions and language, communication and interpretation.', 'Use the curriculum as a map of the ideas, methods and applications you are likely to meet in this programme.', 'A simple explanation of what Accounting studies and how its main subjects fit together.', 'start_here', 'Start here because the CCMAS record is the programme''s national curriculum foundation.', '[]'::jsonb, '["explain-programme-ideas"]'::jsonb, ARRAY['nuc_ccmas','open_reference_administration-and-management']::text[], '[{"id":"nuc_ccmas","title":"NUC CCMAS source page","url":"https://www.nuc.edu.ng/ccmas/","region":"nigeria","evidenceType":"official_curriculum_source"},{"id":"open_reference_administration-and-management","title":"Principles of Management","url":"https://openstax.org/books/principles-management/pages/1-introduction","region":"global","evidenceType":"free_foundation_reference"}]'::jsonb, '[{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"GST 111","courseTitle":"Communication in English","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"GST 112","courseTitle":"Nigerian Peoples and Culture","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"AMS 101","courseTitle":"Principles of Management","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"AMS 102","courseTitle":"Basic Mathematics","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"AMS 103","courseTitle":"Introduction to Computer","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"AMS 104","courseTitle":"Principles of Project Management","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"ACC 101","courseTitle":"Financial Accounting I","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"ACC 102","courseTitle":"Financial Accounting II","level":100}]'::jsonb, 'nigeria_to_global', '["The curriculum record describes what the programme is designed to teach; it does not prove that a student already has the capability.","The open reference is a learning option, not proof that every Nigerian university prescribes that book or course."]'::jsonb),
('Administration and Management', 'Accounting', 'competency', 'explain-programme-ideas', 'Explain the programme''s main ideas', 'This means being able to describe the key ideas in Accounting in your own words and connect them to the course topics.', 'Build this after orientation so the student can tell the difference between memorising course titles and understanding what the programme does.', 'A short explanation, comparison, diagram, calculation, design, experiment, case analysis or other output appropriate to the programme.', 'build_next', 'Build this next because the CCMAS outcomes move from subject knowledge into understanding and application.', '["Understand Accounting"]'::jsonb, '["apply-programme-learning"]'::jsonb, ARRAY['nuc_ccmas','open_reference_administration-and-management']::text[], '[{"id":"nuc_ccmas","title":"NUC CCMAS source page","url":"https://www.nuc.edu.ng/ccmas/","region":"nigeria","evidenceType":"official_curriculum_source"},{"id":"open_reference_administration-and-management","title":"Principles of Management","url":"https://openstax.org/books/principles-management/pages/1-introduction","region":"global","evidenceType":"free_foundation_reference"}]'::jsonb, '[{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"GST 111","courseTitle":"Communication in English","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"GST 112","courseTitle":"Nigerian Peoples and Culture","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"AMS 101","courseTitle":"Principles of Management","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","courseCode":"AMS 102","courseTitle":"Basic Mathematics","level":100},{"sourceFile":"administration_management.json","originalPdf":"Administration-and-Management.pdf","course