INSERT INTO skillup_dev.career_context_items
(context_level, context_key, domain_key, item_type, item_key, name, plain_meaning, contextual_use, expected_output, priority, priority_reason, prerequisites, related_items, source_ids, source_references, source_locators, geographic_scope, evidence_limitations, evidence_type, source_confidence, data_state, verified_at)
SELECT 'programme', p.id::text, COALESCE((SELECT d.domain_key FROM skillup_dev.programme_domain pd JOIN skillup_dev.domains d ON d.id = pd.domain_id WHERE pd.programme_id = p.id ORDER BY CASE lower(pd.match_type) WHEN 'direct' THEN 1 WHEN 'functional' THEN 2 ELSE 3 END, d.domain_key LIMIT 1), 'UNMAPPED'), r.item_type, r.item_key, r.name, r.plain_meaning, r.contextual_use, r.expected_output, r.priority, r.priority_reason, r.prerequisites, r.related_items, r.source_ids, r.source_references, r.source_locators, r.geographic_scope, r.evidence_limitations, 'source_supported_synthesis', 'high', 'source_backed', DATE '2026-09-12'
FROM context_rows r
JOIN skillup_dev.programmes p ON lower(trim(p.discipline)) = lower(trim(r.discipline)) AND lower(trim(p.name)) = lower(trim(r.programme))
ON CONFLICT (context_level, context_key, item_type, item_key) DO UPDATE SET name = EXCLUDED.name, plain_meaning = EXCLUDED.plain_meaning, contextual_use = EXCLUDED.contextual_use, expected_output = EXCLUDED.expected_output, priority = EXCLUDED.priority, priority_reason = EXCLUDED.priority_reason, prerequisites = EXCLUDED.prerequisites, related_items = EXCLUDED.related_items, source_ids = EXCLUDED.source_ids, source_references = EXCLUDED.source_references, source_locators = EXCLUDED.source_locators, geographic_scope = EXCLUDED.geographic_scope, evidence_limitations = EXCLUDED.evidence_limitations, verified_at = EXCLUDED.verified_at;

COMMIT;
